\documentclass{article}
\begin{document}
\section{Introduction}
Recent ocean warming trends motivate the study of microbial adaptation in coastal ecosystems.
\section{Methods}
We sampled twelve sites and describe the experimental setup for metagenomic sequencing.
\section{Conclusion}
Adaptation is faster than expected.
\end{document}

